with cleaned as (select *, year(txn_time) as txn_time_year, coalesce(merchant, 'DIRECT') as resolved_merchant from transactions where txn_type in ('CREDIT', 'FEE', 'DEBIT')), gaps as (select *, case when txn_time - lag(txn_time) over (partition by merchant order by txn_time, id) > interval 60 days then 1 else 0 end as new_group_flag from cleaned), sessionized as (select *, sum(new_group_flag) over (partition by merchant order by txn_time, id rows between unbounded preceding and current row) as session_id from gaps) select case when new_group_flag >= 1 then 'LARGE' else 'SMALL' end as new_group_flag_tier, approx_percentile(new_group_flag, 0.9) as new_group_flag_p90, avg(txn_time_year) as avg_txn_time_year, approx_percentile(txn_time_year, 0.5) as txn_time_year_p50, size(collect_set(merchant)) as num_merchants, count(*) filter (where merchant = 'Grab') as grab_rows, count(*) filter (where merchant = 'Lazada') as lazada_rows from sessionized group by new_group_flag_tier order by avg_txn_time_year desc nulls last
